const CREATOR_DIRECTOR_ACTION_TYPES = new Set<CreatorDirectorActionType>([
  "update_brief_topic",
  "update_strategy_hook",
  "update_scene_script",
  "set_scene_output",
  "update_thumbnail_copy",
  "select_thumbnail_scene",
  "generate_selected_visuals",
  "generate_selected_voice",
  "generate_selected_videos",
  "export_creator_package",
  "navigate_workspace_stage",
]);

function normalizeCreatorDirectorActions(value: unknown): CreatorDirectorAction[] {
  if (!Array.isArray(value)) return [];

  return value
    .slice(0, 2)
    .map((item) => (item && typeof item === "object" ? item as Record<string, any> : {}))
    .filter((item) => CREATOR_DIRECTOR_ACTION_TYPES.has(item.type as CreatorDirectorActionType))
    .map((item, index) => {
      const payload = item.payload && typeof item.payload === "object"
        ? item.payload as Record<string, any>
        : {};
      const renderMode = payload.renderMode === "video"
        ? "video"
        : payload.renderMode === "image"
          ? "image"
          : null;
      const impact: CreatorDirectorActionImpact =
        item.impact === "credit_variable"
          ? "credit_variable"
          : item.impact === "release"
            ? "release"
            : "none";

      return {
        id: String(item.id || `director-action-${Date.now()}-${index}`),
        type: item.type as CreatorDirectorActionType,
        title: String(item.title || "Velto Copilot action").trim().slice(0, 120),
        description: String(item.description || "").trim().slice(0, 420),
        impact,
        requiresExplicitConfirmation: Boolean(item.requiresExplicitConfirmation),
        changes: Array.isArray(item.changes)
          ? item.changes.slice(0, 4).map((change: any) => ({
              label: String(change?.label || "Change").trim().slice(0, 120),
              before: String(change?.before || "—").trim().slice(0, 520),
              after: String(change?.after || "—").trim().slice(0, 520),
            }))
          : [],
        payload: {
          topic: typeof payload.topic === "string" ? payload.topic.trim().slice(0, 1200) || null : null,
          hook: typeof payload.hook === "string" ? payload.hook.trim().slice(0, 1200) || null : null,
          sceneId: Number.isFinite(Number(payload.sceneId)) ? Number(payload.sceneId) : null,
          sceneIds: Array.isArray(payload.sceneIds)
            ? Array.from(new Set(payload.sceneIds.map(Number).filter((id: number) => Number.isFinite(id) && id > 0)))
            : [],
          narration: typeof payload.narration === "string" ? payload.narration.trim().slice(0, 1200) || null : null,
          dialogue: typeof payload.dialogue === "string" ? payload.dialogue.trim().slice(0, 1200) || null : null,
          renderMode,
          thumbnailHeadline:
            typeof payload.thumbnailHeadline === "string"
              ? payload.thumbnailHeadline.trim().slice(0, 160) || null
              : null,
          thumbnailSubHeadline:
            typeof payload.thumbnailSubHeadline === "string"
              ? payload.thumbnailSubHeadline.trim().slice(0, 240) || null
              : null,
          thumbnailSceneId:
            Number.isFinite(Number(payload.thumbnailSceneId))
              ? Number(payload.thumbnailSceneId)
              : null,
          workspaceStage:
            [1, 2, 3, 4].includes(Number(payload.workspaceStage))
              ? (Number(payload.workspaceStage) as 1 | 2 | 3 | 4)
              : null,
        },
        status: "pending" as const,
      };
    });
}

const CREATOR_COPILOT_STORAGE_PREFIX = "velto:creator-copilot:v1";

function getCreatorCopilotStorageKey(
  projectKey: string,
  mode: CreatorDirectorMode,
) {
  const safeProjectKey = String(projectKey || "draft")
    .trim()
    .replace(/[^a-zA-Z0-9._-]/g, "_")
    .slice(0, 160);

  return `${CREATOR_COPILOT_STORAGE_PREFIX}:${safeProjectKey}:${mode}`;
}

function parseCreatorCopilotMessages(value: string | null) {
  if (!value) return [] as CreatorDirectorMessage[];

  try {
    const parsed = JSON.parse(value);

    if (!Array.isArray(parsed)) {
      return [];
    }

    return parsed
      .slice(-30)
      .map((item) =>
        item && typeof item === "object"
          ? (item as Record<string, any>)
          : {},
      )
      .filter(
        (item) =>
          (item.role === "user" || item.role === "assistant") &&
          typeof item.content === "string" &&
          Boolean(item.content.trim()),
      )
      .map((item, index) => ({
        id: String(item.id || `copilot-restored-${Date.now()}-${index}`),
        role: item.role as "user" | "assistant",
        content: String(item.content).trim().slice(0, 5000),
        createdAt:
          typeof item.createdAt === "string"
            ? item.createdAt
            : new Date().toISOString(),
        actions: normalizeCreatorDirectorActions(item.actions).map((action) => ({
          ...action,
          status:
            action.status === "running" ? ("pending" as const) : action.status,
        })),
        intent: [
          "studio_help",
          "creative_direction",
          "project_status",
          "workflow_guidance",
        ].includes(String(item.intent))
          ? item.intent
          : undefined,
        followUps: Array.isArray(item.followUps)
          ? Array.from(
              new Set<string>(
                item.followUps
                  .map((followUp: unknown) =>
                    typeof followUp === "string"
                      ? followUp.trim().slice(0, 180)
                      : "",
                  )
                  .filter(
                    (followUp): followUp is string => Boolean(followUp),
                  ),
              ),
            ).slice(0, 3)
          : [],
        usage:
          item.usage && typeof item.usage === "object"
            ? item.usage
            : null,
      })) as CreatorDirectorMessage[];
  } catch {
    return [];
  }
}

function CreatorWorkspaceIcon({ name }: { name: CreatorWorkspaceIconName }) {
  const sharedProps = {
    width: 20,
    height: 20,
    viewBox: "0 0 24 24",
    fill: "none",
    stroke: "currentColor",
    strokeWidth: 1.8,
    strokeLinecap: "round" as const,
    strokeLinejoin: "round" as const,
    "aria-hidden": true,
  };

  if (name === "ideas") {
    return (
      <svg {...sharedProps}>
        <path d="M9 18h6" />
        <path d="M10 22h4" />
        <path d="M8.5 14.5A6 6 0 1 1 15.5 14.5c-.9.7-1.4 1.5-1.5 2.5h-4c-.1-1-.6-1.8-1.5-2.5Z" />
        <path d="M12 2V1" />
        <path d="m4.9 4.9-.7-.7" />
        <path d="m19.8 4.2-.7.7" />
      </svg>
    );
  }

  if (name === "safety") {
    return (
      <svg {...sharedProps}>
        <path d="M12 3 5.5 5.7v5.1c0 4.4 2.7 8.1 6.5 10.2 3.8-2.1 6.5-5.8 6.5-10.2V5.7L12 3Z" />
        <path d="m9.2 11.8 1.8 1.8 3.9-4" />
      </svg>
    );
  }

  if (name === "package") {
    return (
      <svg {...sharedProps}>
        <path d="m12 3 8 4.4v9.2L12 21l-8-4.4V7.4L12 3Z" />
        <path d="m4.4 7.6 7.6 4.2 7.6-4.2" />
        <path d="M12 12v9" />
        <path d="m8 5.2 8 4.4" />
      </svg>
    );
  }

  return (
    <svg {...sharedProps}>
      <path d="M4 18V9" />
      <path d="M10 18V5" />
      <path d="M16 18v-7" />
      <path d="M22 18V3" />
      <path d="M2 18h22" />
    </svg>
  );
}

