  const [batchRenderStartedAt, setBatchRenderStartedAt] = useState<string>("");
  const [retryingSceneId, setRetryingSceneId] = useState<number | null>(null);
  // VELTO_CANCEL_P1 — provider-confirmed video job cancellation
  const [cancellingVideoSceneId, setCancellingVideoSceneId] = useState<number | null>(null);
  // VELTO_CANCEL_P1_1 — pre-dispatch undo window. No provider request and no
  // Velto credit settlement occurs until this countdown reaches zero.
  const [videoDispatchCountdown, setVideoDispatchCountdown] =
    useState<VideoDispatchCountdown | null>(null);
  const videoDispatchCountdownRef = useRef<VideoDispatchCountdown | null>(null);
  const videoDispatchCountdownTimerRef =
    useRef<ReturnType<typeof setInterval> | null>(null);
  const videoDispatchCountdownResolveRef =
    useRef<((proceed: boolean) => void) | null>(null);
  const [imageDispatchCountdown, setImageDispatchCountdown] =
    useState<ImageDispatchCountdown | null>(null);
  const imageDispatchCountdownRef = useRef<ImageDispatchCountdown | null>(null);
  const imageDispatchCountdownTimerRef =
    useRef<ReturnType<typeof setInterval> | null>(null);
  const imageDispatchCountdownResolveRef =
    useRef<((proceed: boolean) => void) | null>(null);
  const [creatorCostGuardRequest, setCreatorCostGuardRequest] = useState<
    (CreatorCostGuardRequest & { operationId: string }) | null
  >(null);
  const creatorCostGuardResolveRef = useRef<((operationId: string | null) => void) | null>(null);
  const ambiguousCreatorOperationIdsRef = useRef(new Map<string, string>());
  const batchRenderCancelRef = useRef(false);

  const [playingSceneId, setPlayingSceneId] = useState<number | null>(null);
  const [loadingAudioSceneId, setLoadingAudioSceneId] = useState<number | null>(null);
  const [isPlayingStory, setIsPlayingStory] = useState(false);
  const [isPreparingAudio, setIsPreparingAudio] = useState(false);

  const [playingDialogueSceneId, setPlayingDialogueSceneId] = useState<number | null>(null);
  const [loadingDialogueSceneId, setLoadingDialogueSceneId] = useState<number | null>(null);

  const [isExportingMovie, setIsExportingMovie] = useState(false);
  const [exportedMovieUrl, setExportedMovieUrl] = useState("");
  const [exportMovieResult, setExportMovieResult] = useState<ExportMovieResult | null>(null);
  const [exportSignature, setExportSignature] = useState("");

  useEffect(() => {
    return () => {
      if (videoDispatchCountdownTimerRef.current) {
        clearInterval(videoDispatchCountdownTimerRef.current);
      }
      videoDispatchCountdownResolveRef.current?.(false);
      videoDispatchCountdownResolveRef.current = null;
      videoDispatchCountdownRef.current = null;
      if (imageDispatchCountdownTimerRef.current) {
        clearInterval(imageDispatchCountdownTimerRef.current);
      }
      imageDispatchCountdownResolveRef.current?.(false);
      imageDispatchCountdownResolveRef.current = null;
      imageDispatchCountdownRef.current = null;
      creatorCostGuardResolveRef.current?.(null);
      creatorCostGuardResolveRef.current = null;
    };
  }, []);

  const requestCreatorCostGuardConfirmation = (
    request: CreatorCostGuardRequest,
    operationKey?: string,
  ) => {
    if (creatorCostGuardResolveRef.current) return Promise.resolve<string | null>(null);
    const operationId = operationKey
      ? ambiguousCreatorOperationIdsRef.current.get(operationKey) ||
        window.crypto.randomUUID()
      : window.crypto.randomUUID();
    setCreatorCostGuardRequest({ ...request, operationId });
    return new Promise<string | null>((resolve) => {
      creatorCostGuardResolveRef.current = resolve;
    });
  };

  const finishCreatorCostGuardConfirmation = (confirmed: boolean) => {
    const pending = creatorCostGuardRequest;
    const resolve = creatorCostGuardResolveRef.current;
    creatorCostGuardResolveRef.current = null;
    setCreatorCostGuardRequest(null);
    resolve?.(confirmed && pending ? pending.operationId : null);
  };

  const creatorCostGuardHeaders = (operationId: string) => ({
    "x-creator-cost-guard": "creator-cost-guard-v1",
    "x-idempotency-key": operationId,
  });

  const retainAmbiguousCreatorOperationId = (
    operationKey: string,
    operationId: string,
  ) => {
    ambiguousCreatorOperationIdsRef.current.set(operationKey, operationId);
  };

  const retireAmbiguousCreatorOperationId = (
    operationKey: string,
    operationId: string,
  ) => {
    if (ambiguousCreatorOperationIdsRef.current.get(operationKey) === operationId) {
      ambiguousCreatorOperationIdsRef.current.delete(operationKey);
    }
  };

  const isCreatorOperationHttpOutcomeAmbiguous = async (response: Response) => {
    if (response.status === 408 || response.status >= 500) return true;

    const payload = await response.clone().json().catch(() => null);
    return payload?.code === "IDEMPOTENCY_REQUEST_IN_PROGRESS";
  };

  const getCreatorBatchChildOperationKey = (
    operation: "image" | "voice" | "dialogue" | "video",
    sceneId: number,
    imageUseCase?: "scene" | "thumbnail" | "hook",
  ) => [
    "batch-child",
    operation,
    getProjectKey(),
    sceneId,
    ...(operation === "image" ? [imageUseCase || "scene"] : []),
  ].join(":");

  const resolveCreatorBatchChildOperationId = (
    operationKey: string | undefined,
    derivedOperationId: string,
  ) => operationKey
    ? ambiguousCreatorOperationIdsRef.current.get(operationKey) || derivedOperationId
    : derivedOperationId;

  const getCreatorTelemetrySessionId = () => {
    if (typeof window === "undefined") return "server";

    const storageKey = "velto.creatorlab.telemetry-session";
    const existing = window.sessionStorage.getItem(storageKey);
    if (existing) return existing;

    const next =
      typeof window.crypto?.randomUUID === "function"
        ? window.crypto.randomUUID()
        : `creator-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
    window.sessionStorage.setItem(storageKey, next);
    return next;
  };

  const emitCreatorTelemetry = async (
    eventName: CreatorTelemetryEventName,
    metadata: Record<string, string | number | boolean | null> = {},
  ) => {
    if (!isCreatorLabFlow) return;

    setCreatorTelemetryLastEvent(eventName);

    try {
      const {
        data: { session },
      } = await supabase.auth.getSession();
      const token = session?.access_token;
      if (!token) return;

      await fetch("/api/creator-analytics", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        keepalive: true,
        body: JSON.stringify({
          eventName,
          sessionId: getCreatorTelemetrySessionId(),
          stage: creatorWorkspaceStep,
          projectState: currentProjectId ? "saved" : "draft",
          metadata,
        }),
      });
    } catch (telemetryError) {
      console.warn("Velto Studio telemetry delivery failed:", telemetryError);
    }
  };

  const handleCreatorOutcomeSelect = (nextOutcome: CreatorOutcome) => {
    const definition = getCreatorOutcomeDefinition(nextOutcome);
    const nextContentType = definition.defaults.contentType || creatorContentType;

    setCreatorOutcome(nextOutcome);
    setCreatorFormat(definition.defaults.format);
    setCreatorDurationPreset(definition.defaults.durationPreset);
    setCreatorVideoDurationSec(definition.defaults.durationSeconds);
    setCreatorCustomDurationSec(definition.defaults.durationSeconds);
    setCreatorTargetPlatforms([...definition.defaults.targetPlatforms]);
    if (definition.defaults.contentType) {
      setCreatorContentType(definition.defaults.contentType);
    }

    void emitCreatorTelemetry("outcome_selected", {
      outcome: nextOutcome,
      format: definition.defaults.format,
      contentType: nextContentType,
      durationSeconds: definition.defaults.durationSeconds,
      targetPlatformCount: definition.defaults.targetPlatforms.length,
    });
  };

  const refreshCreatorOpsStatus = async (): Promise<CreatorOpsStatus | null> => {
    if (!isCreatorLabFlow) return null;

    setCreatorOpsStatus((previous) => ({
      ...previous,
      status: "checking",
      message: "",
    }));

    try {
      const {
        data: { session },
      } = await supabase.auth.getSession();
      const token = session?.access_token;

      if (!token) {
        throw new Error(
          uiLanguage === "en"
            ? "A valid session is required for the operational check."
            : "Operasyon kontrolü için geçerli oturum gerekli.",
        );
      }

      const response = await fetch("/api/creator-health", {
        method: "GET",
        headers: {
          Authorization: `Bearer ${token}`,
        },
        cache: "no-store",
      });
      const data = await response.json().catch(() => null);

      if (!response.ok || !data) {
        throw new Error(
          data?.error ||
            (uiLanguage === "en"
              ? "Velto Studio operational status could not be checked."
              : "Velto Studio operasyon durumu kontrol edilemedi."),
        );
      }

      const nextStatus: CreatorOpsStatus = {
        status:
          data.status === "ready" ||
          data.status === "degraded" ||
          data.status === "blocked"
            ? data.status
            : "error",
        checkedAt: typeof data.checkedAt === "string" ? data.checkedAt : "",
        release: typeof data.release === "string" ? data.release : "",
        requestId: typeof data.requestId === "string" ? data.requestId : "",
        services: {
          database: Boolean(data.services?.database),
          ai: Boolean(data.services?.ai),
          voice: Boolean(data.services?.voice),
          video: Boolean(data.services?.video),
          export: Boolean(data.services?.export),
        },
        message: typeof data.message === "string" ? data.message : "",
      };

      setCreatorOpsStatus(nextStatus);
      return nextStatus;
    } catch (opsError) {
      const nextStatus: CreatorOpsStatus = {
        status: "error",
        checkedAt: new Date().toISOString(),
        release: "",
        requestId: "",
        services: {
          database: false,
          ai: false,
          voice: false,
          video: false,
          export: false,
        },
        message:
          opsError instanceof Error
            ? opsError.message
            : uiLanguage === "en"
              ? "Velto Studio operational status could not be checked."
              : "Velto Studio operasyon durumu kontrol edilemedi.",
      };

      setCreatorOpsStatus(nextStatus);
      return nextStatus;
    }
  };

  useEffect(() => {
    if (!creatorPackageDownloaded || !creatorPackageSignature) {
      return;
    }

    const currentSignature = createCreatorPublishArtifactSignature({
      finalVideoSignature: exportSignature || buildExportSignature(title, scenes),
      metadata: youtubeMetadataResult,
      thumbnail: youtubeThumbnailResult,
      thumbnailDesign: creatorThumbnailStudio,
      targetPlatforms: creatorTargetPlatforms,
      creatorFormat,
      qualityMode: creatorQualityMode,
    });

    if (currentSignature !== creatorPackageSignature) {
      setCreatorPackageDownloaded(false);
    }
  }, [
    creatorFormat,
    creatorPackageDownloaded,
    creatorPackageSignature,
    creatorProductionPackage,
    creatorQualityMode,
    creatorTargetPlatforms,
    creatorThumbnailStudio,
    exportSignature,
    scenes,
    title,
    youtubeMetadataResult,
    youtubeThumbnailResult,
  ]);

  useEffect(() => {
    const availableSceneIds = new Set(scenes.map((scene) => scene.id));
    setCreatorSelectedSceneIds((prev) => {
      const next = prev.filter((sceneId) => availableSceneIds.has(sceneId));
      return next.length === prev.length && next.every((sceneId, index) => sceneId === prev[index])
        ? prev
        : next;
    });
    setCreatorAssetCompareSelection((prev) => {
      const entries = Object.entries(prev).filter(([sceneId]) =>
        availableSceneIds.has(Number(sceneId)),
      );
      return entries.length === Object.keys(prev).length
        ? prev
        : Object.fromEntries(entries);
    });
  }, [scenes]);

  useEffect(() => {
    if (!isCreatorLabFlow || scenes.length === 0) {
      return;
    }

    setScenes((prev) => {
      let changed = false;
      const next = prev.map((scene) => {
        const normalized = normalizeCreatorAssetHistory(scene);
        if (normalized !== scene) {
          changed = true;
        }
        return normalized;
      });
      return changed ? next : prev;
    });
  }, [isCreatorLabFlow, scenes]);

  useEffect(() => {
    if (!isCreatorLabFlow) {
      setSelectedCreatorEditorSceneId(null);
      setCreatorEditorOpen(false);
      return;
    }

    setSelectedCreatorEditorSceneId((current) =>
      selectCreatorSceneId(scenes, current),
    );
  }, [isCreatorLabFlow, scenes]);


  useEffect(() => {
    const headline =
      youtubeThumbnailResult?.headline ||
      youtubeMetadataResult?.thumbnailTextIdeas?.[0] ||
      youtubeMetadataResult?.recommendedTitle ||
      creatorProductionPackage?.youtubeTitle ||
      creatorProductionPackage?.title ||
      "";
    const subHeadline =
      youtubeThumbnailResult?.subHeadline ||
      youtubeMetadataResult?.thumbnailTextIdeas?.[1] ||
      creatorProductionPackage?.hook ||
      "";

    setCreatorThumbnailStudio((prev) => ({
      ...prev,
      headline: prev.headline.trim() ? prev.headline : headline,
      subHeadline: prev.subHeadline.trim() ? prev.subHeadline : subHeadline,
    }));
  }, [
    youtubeThumbnailResult?.headline,
    youtubeThumbnailResult?.subHeadline,
    youtubeMetadataResult?.recommendedTitle,
    youtubeMetadataResult?.thumbnailTextIdeas,
    creatorProductionPackage?.youtubeTitle,
    creatorProductionPackage?.title,
    creatorProductionPackage?.hook,
  ]);

  useEffect(() => {
    setCreatorReleaseConfirmations((prev) => ({ ...prev, videoReviewed: false }));
  }, [exportedMovieUrl, exportMovieResult?.movieUrl, exportMovieResult?.downloadUrl]);

  useEffect(() => {
    setCreatorReleaseConfirmations((prev) => ({ ...prev, thumbnailApproved: false }));
  }, [youtubeThumbnailResult?.imageUrl, creatorThumbnailStudio.headline, creatorThumbnailStudio.subHeadline]);

  const creatorThumbnailHasUnsavedChanges =
    JSON.stringify(creatorThumbnailStudio) !== JSON.stringify(creatorThumbnailSavedDesign);

  useEffect(() => {
    if (!youtubeThumbnailResult?.imageUrl) return;
    setCreatorThumbnailSavedDesign({ ...creatorThumbnailStudio });
  // A newly selected or generated source becomes the initial saved design.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [youtubeThumbnailResult?.imageUrl]);

  useEffect(() => {
    if (typeof window === "undefined") return;
    try {
      const stored = window.localStorage.getItem("velto:creator-thumbnail-history");
      if (!stored) return;
      const parsed = JSON.parse(stored);
      if (Array.isArray(parsed)) setCreatorThumbnailHistory(parsed.slice(0, 10));
    } catch (historyError) {
      console.warn("Thumbnail history could not be restored.", historyError);
    }
  }, []);

  useEffect(() => {
    if (typeof window === "undefined") return;
    try {
      window.localStorage.setItem(
        "velto:creator-thumbnail-history",
        JSON.stringify(creatorThumbnailHistory.slice(0, 10)),
      );
    } catch (historyError) {
      console.warn("Thumbnail history could not be saved.", historyError);
    }
  }, [creatorThumbnailHistory]);

  useEffect(() => {
    setCreatorReleaseConfirmations((prev) => ({ ...prev, claimsVerified: false }));
  }, [youtubeMetadataResult?.recommendedTitle, youtubeMetadataResult?.description]);

  useEffect(() => {
    setYoutubeThumbnailResult((prev) => {
      if (!prev) return prev;
      const nextHeadline = creatorThumbnailStudio.headline || prev.headline;
      const nextSubHeadline = creatorThumbnailStudio.subHeadline || prev.subHeadline;
      if (
        prev.headline === nextHeadline &&
        prev.subHeadline === nextSubHeadline &&
        JSON.stringify(prev.design || null) === JSON.stringify(creatorThumbnailStudio)
      ) {
        return prev;
      }
      return {
        ...prev,
        headline: nextHeadline,
        subHeadline: nextSubHeadline,
        design: creatorThumbnailStudio,
      };
    });
  }, [creatorThumbnailStudio]);

